"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import type { Session } from "@supabase/supabase-js";
import { ApiError, fetchAdminMe, type AdminMeResponse } from "../../lib/admin/api";
import { supabase, cleanLegacyLocalStorageAuth } from "../../lib/admin/supabase";

export type AdminUser = AdminMeResponse["user"];

export type AuthStatus = "loading" | "authenticated" | "unauthenticated";

export type AuthContextType = {
  status: AuthStatus;
  user: AdminUser | null;
  session: Session | null;
  error: string | null;
  signIn: (email: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
  clearError: () => void;
};

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [status, setStatus] = useState<AuthStatus>("loading");
  const [user, setUser] = useState<AdminUser | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Keep references to latest user and status to avoid stale closures in auth listeners
  const userRef = useRef<AdminUser | null>(null);
  userRef.current = user;
  const statusRef = useRef<AuthStatus>("loading");
  statusRef.current = status;

  // Prevent race conditions during rapid state transitions
  const verificationSeq = useRef(0);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  const verifyBackendAuthorization = useCallback(
    async (_currentSession?: Session): Promise<AdminUser | null> => {
      const seq = ++verificationSeq.current;
      try {
        const response = await fetchAdminMe();
        if (seq !== verificationSeq.current) return null;
        return response.user;
      } catch (err: unknown) {
        if (seq !== verificationSeq.current) return null;

        // If backend returns 403 Forbidden, the Supabase user is not an active Electro Tech admin
        if (err instanceof ApiError && err.status === 403) {
          await supabase.auth.signOut();
          setError("This account is not authorized to access the Electro Tech admin portal.");
          return null;
        }

        // If 401 or token is invalid, sign out
        if (err instanceof ApiError && err.status === 401) {
          await supabase.auth.signOut();
          setError("Invalid or expired session. Please sign in again.");
          return null;
        }

        // Infrastructure or connection issue
        setError("Admin authorization service is temporarily unavailable. Please try again later.");
        return null;
      }
    },
    [],
  );

  useEffect(() => {
    let isMounted = true;
    cleanLegacyLocalStorageAuth();

    // Listen to Supabase auth state changes
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, newSession) => {
      if (!isMounted) return;

      // Handle sign-out or missing session
      if (event === "SIGNED_OUT" || !newSession) {
        setSession(null);
        setUser(null);
        setStatus("unauthenticated");
        return;
      }

      // Always update current session with newest JWT
      setSession(newSession);

      // 1. TOKEN_REFRESHED: Background token rotation
      // Must NOT set status to "loading" and must NOT remount the protected application.
      if (event === "TOKEN_REFRESHED") {
        // If the user is already authenticated with the same user ID, session update is complete
        if (userRef.current && userRef.current.userId === newSession.user.id) {
          return;
        }

        // If user identity changed or was not yet set, verify in background
        const verifiedUser = await verifyBackendAuthorization(newSession);
        if (!isMounted) return;

        if (verifiedUser) {
          setUser(verifiedUser);
          setStatus("authenticated");
          setError(null);
        } else {
          setUser(null);
          setStatus("unauthenticated");
        }
        return;
      }

      // 2. SIGNED_IN: Can fire on fresh login or on window focus / re-connect
      if (event === "SIGNED_IN") {
        // If already authenticated as the same user, treat as a background session refresh
        if (
          userRef.current &&
          userRef.current.userId === newSession.user.id &&
          statusRef.current === "authenticated"
        ) {
          return;
        }

        // Otherwise, perform verification
        if (statusRef.current !== "loading") {
          setStatus("loading");
        }
        const verifiedUser = await verifyBackendAuthorization(newSession);
        if (!isMounted) return;

        if (verifiedUser) {
          setUser(verifiedUser);
          setStatus("authenticated");
          setError(null);
        } else {
          setUser(null);
          setStatus("unauthenticated");
        }
        return;
      }

      // 3. INITIAL_SESSION: Application bootstrap
      if (event === "INITIAL_SESSION") {
        setStatus("loading");
        const verifiedUser = await verifyBackendAuthorization(newSession);
        if (!isMounted) return;

        if (verifiedUser) {
          setUser(verifiedUser);
          setStatus("authenticated");
          setError(null);
        } else {
          setUser(null);
          setStatus("unauthenticated");
        }
      }
    });

    return () => {
      isMounted = false;
      subscription.unsubscribe();
    };
  }, [verifyBackendAuthorization]);

  const signIn = useCallback(
    async (email: string, password: string): Promise<void> => {
      setError(null);
      setStatus("loading");

      const trimmedEmail = email.trim();
      if (!trimmedEmail || !password) {
        setStatus("unauthenticated");
        setError("Email and password are required.");
        throw new Error("Email and password are required.");
      }

      cleanLegacyLocalStorageAuth();

      // 1. Authenticate with Supabase Auth
      const { data, error: authError } = await supabase.auth.signInWithPassword({
        email: trimmedEmail,
        password,
      });

      if (authError || !data.session) {
        setStatus("unauthenticated");
        setUser(null);
        setSession(null);
        const genericError = "Invalid email or password.";
        setError(genericError);
        throw new Error(genericError);
      }

      // 2. Verify backend authorization
      setSession(data.session);
      const verifiedUser = await verifyBackendAuthorization(data.session);

      if (!verifiedUser) {
        setStatus("unauthenticated");
        setUser(null);
        setSession(null);
        throw new Error(
          error ?? "This account is not authorized to access the Electro Tech admin portal.",
        );
      }

      setUser(verifiedUser);
      setStatus("authenticated");
      setError(null);
    },
    [error, verifyBackendAuthorization],
  );

  const signOut = useCallback(async (): Promise<void> => {
    try {
      await supabase.auth.signOut();
      cleanLegacyLocalStorageAuth();
    } finally {
      setSession(null);
      setUser(null);
      setStatus("unauthenticated");
      setError(null);
    }
  }, []);

  return (
    <AuthContext.Provider
      value={{
        status,
        user,
        session,
        error,
        signIn,
        signOut,
        clearError,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

"use client";

import { useEffect, useState } from "react";
import { fetchAdminProjects } from "../../lib/admin/api";
import { StatusBadge } from "./StatusBadge";
import type { AdminProject } from "../../types/admin/project";

export function DashboardPage() {
  const [projects, setProjects] = useState<AdminProject[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    async function loadData() {
      try {
        setIsLoading(true);
        setError(null);
        const data = await fetchAdminProjects("all");
        if (mounted) {
          setProjects(data);
        }
      } catch (err) {
        if (mounted) {
          setError(
            err instanceof Error ? err.message : "Failed to load project metrics.",
          );
        }
      } finally {
        if (mounted) {
          setIsLoading(false);
        }
      }
    }

    loadData();
    return () => {
      mounted = false;
    };
  }, []);

  const totalCount = projects.length;
  const publishedCount = projects.filter((p) => p.status === "published").length;
  const draftCount = projects.filter((p) => p.status === "draft").length;
  const archivedCount = projects.filter((p) => p.status === "archived").length;

  const recentProjects = [...projects]
    .sort(
      (a, b) =>
        new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
    )
    .slice(0, 5);

  return (
    <div>
      <div className="page-header">
        <div className="page-title-group">
          <h1>Projects Overview</h1>
          <p>Monitor, manage, and publish commercial & residential solar installations</p>
        </div>
        <div className="page-actions">
          <a href="/admin/projects/new" className="btn btn-primary">
            + Create Project
          </a>
          <a href="/admin/projects" className="btn btn-secondary">
            View All Projects
          </a>
        </div>
      </div>

      {error && (
        <div className="alert-banner alert-danger" role="alert">
          <span>{error}</span>
        </div>
      )}

      {isLoading ? (
        <div className="loading-container" role="status" aria-live="polite">
          <div className="spinner" />
          <p>Loading dashboard metrics...</p>
        </div>
      ) : (
        <>
          <div className="stats-grid">
            <div className="stat-card">
              <span className="stat-label">Total Projects</span>
              <span className="stat-value">{totalCount}</span>
              <span className="stat-hint">Across all lifecycles</span>
            </div>
            <div className="stat-card">
              <span className="stat-label">Published</span>
              <span className="stat-value" style={{ color: "var(--color-success)" }}>
                {publishedCount}
              </span>
              <span className="stat-hint">Active on public website</span>
            </div>
            <div className="stat-card">
              <span className="stat-label">Drafts</span>
              <span className="stat-value" style={{ color: "var(--color-warning)" }}>
                {draftCount}
              </span>
              <span className="stat-hint">Unpublished / in progress</span>
            </div>
            <div className="stat-card">
              <span className="stat-label">Archived</span>
              <span className="stat-value" style={{ color: "var(--color-archived)" }}>
                {archivedCount}
              </span>
              <span className="stat-hint">Inactive / hidden from public</span>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <div>
                <h2 className="card-title">Recently Updated Projects</h2>
                <p className="card-desc">Quick access to recently modified installations</p>
              </div>
              <a href="/admin/projects" className="btn btn-secondary btn-sm">
                See all
              </a>
            </div>

            {recentProjects.length === 0 ? (
              <div className="empty-state">
                <h3 className="empty-state-title">No projects found</h3>
                <p className="empty-state-desc">
                  Get started by creating your first solar project record.
                </p>
                <a href="/admin/projects/new" className="btn btn-primary">
                  Create Project
                </a>
              </div>
            ) : (
              <div className="table-container">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th style={{ width: "60px" }}>Image</th>
                      <th>Project</th>
                      <th>Status</th>
                      <th>Location</th>
                      <th>Size</th>
                      <th>Last Updated</th>
                      <th style={{ textAlign: "right" }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentProjects.map((project) => {
                      const thumbUrl =
                        project.mainMedia?.publicUrl ||
                        project.primaryImageUrl ||
                        project.media?.find((m) => m.isPrimary)?.publicUrl ||
                        project.media?.[0]?.publicUrl;

                      return (
                        <tr key={project.id}>
                          <td>
                            {thumbUrl ? (
                              <img
                                src={thumbUrl}
                                alt={project.primaryAlt || project.title}
                                className="table-thumb"
                              />
                            ) : (
                              <div className="table-thumb-placeholder">No img</div>
                            )}
                          </td>
                          <td>
                            <div className="project-title-cell">
                              <a
                                href={`/admin/projects/${project.id}/edit`}
                                className="project-title-link"
                              >
                                {project.title}
                              </a>
                              <span className="project-slug-text">
                                /{project.slug}
                              </span>
                            </div>
                          </td>
                          <td>
                            <StatusBadge
                              status={project.status}
                              isFeaturedHomepage={project.isFeaturedHomepage}
                            />
                          </td>
                          <td>{project.location || "—"}</td>
                          <td>{project.size || "—"}</td>
                          <td style={{ color: "var(--text-secondary)", fontSize: "0.8rem" }}>
                            {new Date(project.updatedAt).toLocaleDateString()}
                          </td>
                          <td>
                            <div className="table-actions">
                              <a
                                href={`/admin/projects/${project.id}/preview`}
                                className="btn btn-secondary btn-sm"
                              >
                                Preview
                              </a>
                              <a
                                href={`/admin/projects/${project.id}/edit`}
                                className="btn btn-secondary btn-sm"
                              >
                                Edit
                              </a>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

import { useEffect } from "react";

type DeleteConfirmModalProps = {
  isOpen: boolean;
  projectTitle: string;
  onConfirm: () => Promise<void>;
  onCancel: () => void;
  isDeleting: boolean;
};

export function DeleteConfirmModal({
  isOpen,
  projectTitle,
  onConfirm,
  onCancel,
  isDeleting,
}: DeleteConfirmModalProps) {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen && !isDeleting) {
        onCancel();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, isDeleting, onCancel]);

  if (!isOpen) return null;

  return (
    <div
      className="modal-backdrop"
      onClick={() => {
        if (!isDeleting) onCancel();
      }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
    >
      <div
        className="modal-dialog"
        onClick={(e) => e.stopPropagation()}
      >
        <h3 id="modal-title" className="modal-title">
          Delete Project
        </h3>
        <p className="modal-body">
          Are you sure you want to permanently delete <strong>{projectTitle}</strong>?
          <br />
          <br />
          This will permanently remove the project record and delete all associated image assets
          from storage. <strong>This action cannot be undone.</strong>
        </p>
        <div className="modal-actions">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={onCancel}
            disabled={isDeleting}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-danger"
            onClick={onConfirm}
            disabled={isDeleting}
          >
            {isDeleting ? (
              <>
                <span className="spinner-sm" /> Deleting...
              </>
            ) : (
              "Permanently Delete"
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState, useRef, type ChangeEvent } from "react";
import type { ProjectImageSlot } from "../../types/admin/project";

type ImageSlotManagerProps = {
  slot: ProjectImageSlot;
  imageUrl: string | null;
  altText?: string | null;
  position?: string;
  onUpload: (file: File) => Promise<void>;
  onDelete: () => Promise<void>;
  disabled?: boolean;
};

const MAX_FILE_BYTES = 5 * 1024 * 1024; // 5 MB

export function ImageSlotManager({
  slot,
  imageUrl,
  altText,
  position = "center",
  onUpload,
  onDelete,
  disabled = false,
}: ImageSlotManagerProps) {
  const [isUploading, setIsUploading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const slotLabel = slot === "primary" ? "Primary Image" : "Secondary Image";
  const slotHint =
    slot === "primary"
      ? "Required for publishing. Displayed in project card grid."
      : "Optional. Displayed when project card is expanded.";

  const handleFileChange = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);

    // Validate size on client before uploading
    if (file.size > MAX_FILE_BYTES) {
      setError("File exceeds the 5 MB size limit.");
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }

    // Validate type on client
    const validTypes = ["image/jpeg", "image/png", "image/webp"];
    if (!validTypes.includes(file.type)) {
      setError("Only JPEG, PNG, and WebP images are allowed.");
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }

    try {
      setIsUploading(true);
      await onUpload(file);
      if (fileInputRef.current) fileInputRef.current.value = "";
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to upload image.");
    } finally {
      setIsUploading(false);
    }
  };

  const handleDelete = async () => {
    if (!imageUrl || isDeleting) return;
    setError(null);

    try {
      setIsDeleting(true);
      await onDelete();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to delete image.");
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <div className="image-slot-card">
      <div className="image-slot-header">
        <div>
          <h4 className="image-slot-title">{slotLabel}</h4>
          <p className="form-hint">{slotHint}</p>
        </div>
        {imageUrl ? (
          <span className="badge badge-published">Uploaded</span>
        ) : (
          <span className="badge badge-draft">Empty</span>
        )}
      </div>

      {error && (
        <div className="alert-banner alert-danger" role="alert">
          <span>{error}</span>
        </div>
      )}

      <div className="image-preview-box">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={altText || `${slotLabel} preview`}
            className="image-preview-img"
            style={{ objectPosition: position }}
          />
        ) : (
          <div className="image-preview-empty">
            <svg
              width="32"
              height="32"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <rect width="18" height="18" x="3" y="3" rx="2" ry="2" />
              <circle cx="9" cy="9" r="2" />
              <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21" />
            </svg>
            <span>No image uploaded</span>
          </div>
        )}
      </div>

      <div className="image-slot-actions">
        <div className="image-upload-row">
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/jpeg,image/png,image/webp"
            className="image-file-input"
            id={`file-input-${slot}`}
            disabled={disabled || isUploading || isDeleting}
          />

          <label
            htmlFor={`file-input-${slot}`}
            className={`btn btn-secondary ${disabled || isUploading ? "disabled" : ""}`}
            style={{ cursor: disabled || isUploading ? "not-allowed" : "pointer", flex: 1 }}
          >
            {isUploading ? (
              <>
                <span className="spinner-sm" /> Uploading...
              </>
            ) : imageUrl ? (
              "Replace Image"
            ) : (
              "Upload Image"
            )}
          </label>

          {imageUrl && (
            <button
              type="button"
              className="btn btn-outline-danger"
              onClick={handleDelete}
              disabled={disabled || isUploading || isDeleting}
              aria-label={`Delete ${slotLabel}`}
            >
              {isDeleting ? <span className="spinner-sm" /> : "Delete"}
            </button>
          )}
        </div>
        <p className="form-hint" style={{ textAlign: "center" }}>
          JPEG, PNG, or WebP &bull; Max 5 MB
        </p>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, type FormEvent } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuth } from "./useAuth";

export function LoginPage() {
  const { status, error, signIn, clearError } = useAuth();
  const router = useRouter();
  const searchParams = useSearchParams();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState<string | null>(null);

  const from = searchParams.get("from") || "/admin";

  useEffect(() => {
    if (status === "authenticated") {
      router.replace(from);
    }
  }, [status, from, router]);

  // If already authenticated and authorized, redirect to admin home
  if (status === "authenticated") {
    return (
      <div className="loading-container" role="status" aria-live="polite">
        <div className="spinner" />
        <p>Redirecting...</p>
      </div>
    );
  }

  // If still checking initial session on client, show loading
  if (typeof window !== "undefined" && status === "loading" && !isSubmitting) {
    return (
      <div className="loading-container" role="status" aria-live="polite">
        <div className="spinner" />
        <p>Checking session...</p>
      </div>
    );
  }

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setLocalError(null);
    clearError();

    const trimmedEmail = email.trim();
    if (!trimmedEmail || !password) {
      setLocalError("Please enter both email and password.");
      return;
    }

    try {
      setIsSubmitting(true);
      await signIn(trimmedEmail, password);
      router.replace(from);
    } catch {
      // Clear password on error as a security best practice
      setPassword("");
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayedError = localError || error;

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-header">
          <div className="auth-brand">
            <img
              src="/logos/electrotech-horizontal.png"
              alt="Electro Tech"
              className="auth-logo-img"
            />
            <span className="auth-badge">Admin Portal</span>
          </div>
          <h1 className="auth-title">Sign In</h1>
          <p className="auth-subtitle">Authorized personnel only</p>
        </div>

        {displayedError && (
          <div className="alert-banner alert-danger" role="alert">
            <span>{displayedError}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} noValidate>
          <div className="form-group">
            <label htmlFor="email" className="form-label">
              Email Address
            </label>
            <input
              id="email"
              type="email"
              className="form-input"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="admin@electrotech.pk"
              required
              autoFocus
              autoComplete="username"
              disabled={isSubmitting}
            />
          </div>

          <div className="form-group">
            <label htmlFor="password" className="form-label">
              Password
            </label>
            <div className="input-wrapper">
              <input
                id="password"
                type={showPassword ? "text" : "password"}
                className="form-input"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                required
                autoComplete="current-password"
                disabled={isSubmitting}
              />
              <button
                type="button"
                className="password-toggle-btn"
                onClick={() => setShowPassword((prev) => !prev)}
                aria-label={showPassword ? "Hide password" : "Show password"}
                disabled={isSubmitting}
              >
                {showPassword ? "Hide" : "Show"}
              </button>
            </div>
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            disabled={isSubmitting}
          >
            {isSubmitting ? "Signing in..." : "Sign In"}
          </button>
        </form>
      </div>
    </div>
  );
}

