source:
"use client";

import { useEffect, useState, type FormEvent } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  archiveAdminProject,
  deleteAdminProject,
  fetchAdminProjectById,
  fetchAdminProjects,
  publishAdminProject,
  restoreAdminProject,
  unpublishAdminProject,
  updateAdminHomepageProjects,
  updateAdminProject,
  ApiError,
} from "../../lib/admin/api";
import { ProjectReviewsManager } from "./ProjectReviewsManager";
import { StatusBadge } from "./StatusBadge";
import { ProjectMediaManager } from "./ProjectMediaManager";
import { DeleteConfirmModal } from "./DeleteConfirmModal";
import {
  clearProjectDraft,
  getEditProjectDraftKey,
  getProjectDraft,
  saveProjectDraft,
} from "../../lib/admin/draft-storage";
import {
  PROJECT_CATEGORIES,
  type AdminProject,
  type ProjectCategory,
  type UpdateProjectPayload,
} from "../../types/admin/project";

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function ProjectEditPage({ projectId }: { projectId?: string }) {
  const params = useParams();
  const pathnameFallback =
    typeof window !== "undefined"
      ? window.location.pathname.match(/\/admin\/projects\/([^/]+)\/(?:edit|preview)/)?.[1]
      : undefined;
  const paramId =
    typeof params?.id === "string"
      ? params.id
      : Array.isArray(params?.id)
        ? params.id[0]
        : undefined;
  const rawId = (typeof projectId === "string" && projectId.trim()) || paramId || pathnameFallback;
  const id = typeof rawId === "string" ? rawId.trim() : "";
  const router = useRouter();

  const [project, setProject] = useState<AdminProject | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isOperatingLifecycle, setIsOperatingLifecycle] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Form state
  const [title, setTitle] = useState("");
  const [autoSlug, setAutoSlug] = useState(false);
  const [slug, setSlug] = useState("");
  const [clientOrganization, setClientOrganization] = useState("");
  const [locationField, setLocationField] = useState("");
  const [size, setSize] = useState("");
  const [category, setCategory] = useState<ProjectCategory | "">("");
  const [completionDate, setCompletionDate] = useState<string>("");
  const [shortSummary, setShortSummary] = useState("");
  const [fullStory, setFullStory] = useState("");

  const loadProject = async (projId: string) => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchAdminProjectById(projId);
      setProject(data);

      // Check if there is an unsaved local draft for this specific project
      const draft = getProjectDraft(getEditProjectDraftKey(projId));

      if (draft) {
        setTitle(draft.title !== undefined ? draft.title : data.title);
        setAutoSlug(draft.autoSlug !== undefined ? draft.autoSlug : false);
        setSlug(draft.slug !== undefined ? draft.slug : data.slug);
        setClientOrganization(
          draft.clientOrganization !== undefined
            ? (draft.clientOrganization || "")
            : (data.clientOrganization || ""),
        );
        setLocationField(
          draft.location !== undefined ? (draft.location || "") : (data.location || ""),
        );
        setSize(draft.size !== undefined ? (draft.size || "") : (data.size || ""));
        setCategory(
          draft.category !== undefined
            ? (draft.category as ProjectCategory) || ""
            : (data.category as ProjectCategory) || "",
        );
        setCompletionDate(
          draft.completionDate !== undefined
            ? draft.completionDate ? String(draft.completionDate) : ""
            : data.completionDate ? String(data.completionDate) : "",
        );
        setShortSummary(
          draft.shortSummary !== undefined ? (draft.shortSummary || "") : (data.shortSummary || ""),
        );
        setFullStory(
          draft.fullStory !== undefined ? (draft.fullStory || "") : (data.fullStory || ""),
        );
      } else {
        // Baseline from server
        setTitle(data.title);
        setAutoSlug(false);
        setSlug(data.slug);
        setClientOrganization(data.clientOrganization || "");
        setLocationField(data.location || "");
        setSize(data.size || "");
        setCategory((data.category as ProjectCategory) || "");
        setCompletionDate(data.completionDate ? String(data.completionDate) : "");
        setShortSummary(data.shortSummary || "");
        setFullStory(data.fullStory || "");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load project.");
    } finally {
      setIsLoading(false);
    }
  };

  const refreshProjectMedia = async (projectId: string) => {
    try {
      const data = await fetchAdminProjectById(projectId);
      setProject(data);
    } catch (err) {
      console.error("Failed to refresh project data:", err);
    }
  };

  useEffect(() => {
    if (id) {
      loadProject(id);
    }
  }, [id]);

  // Handle title changes and auto-slug generation
  const handleTitleChange = (newTitle: string) => {
    setTitle(newTitle);
    if (autoSlug) {
      setSlug(slugify(newTitle));
    }
  };

  // Handle manual slug changes
  const handleSlugChange = (newSlug: string) => {
    setAutoSlug(false);
    setSlug(newSlug.toLowerCase());
  };

  // Compute dirty state against server baseline
  const isDirty = Boolean(
    project &&
      (title !== project.title ||
        slug !== project.slug ||
        clientOrganization !== (project.clientOrganization || "") ||
        locationField !== (project.location || "") ||
        size !== (project.size || "") ||
        category !== (project.category || "") ||
        completionDate !== (project.completionDate ? String(project.completionDate) : "") ||
        shortSummary !== (project.shortSummary || "") ||
        fullStory !== (project.fullStory || "")),
  );

  // Auto-save local draft to sessionStorage whenever fields differ from server
  useEffect(() => {
    if (!id || !project) return;

    if (isDirty) {
      saveProjectDraft(getEditProjectDraftKey(id), {
        title,
        slug,
        autoSlug,
        clientOrganization,
        location: locationField,
        size,
        category: category || null,
        completionDate: completionDate || null,
        shortSummary,
        fullStory,
      });
    } else {
      clearProjectDraft(getEditProjectDraftKey(id));
    }
  }, [
    id,
    project,
    isDirty,
    title,
    slug,
    autoSlug,
    clientOrganization,
    locationField,
    size,
    category,
    completionDate,
    shortSummary,
    fullStory,
  ]);

  // Warn administrator on browser reload or tab close if unsaved work exists
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (isDirty) {
        e.preventDefault();
      }
    };
    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => window.removeEventListener("beforeunload", handleBeforeUnload);
  }, [isDirty]);

  const handleSaveMetadata = async (e: FormEvent) => {
    e.preventDefault();
    if (!id || isSaving) return;

    setError(null);
    setSuccessMessage(null);

    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError("Project title cannot be empty.");
      return;
    }

    const payload: UpdateProjectPayload = {
      title: trimmedTitle,
      slug: slug.trim() || undefined,
      clientOrganization: clientOrganization.trim() || null,
      location: locationField.trim() || null,
      size: size.trim() || null,
      category: category ? (category as ProjectCategory) : null,
      completionDate: completionDate || null,
      shortSummary: shortSummary.trim() || null,
      fullStory: fullStory.trim() || null,
    };

    try {
      setIsSaving(true);
      const updated = await updateAdminProject(id, payload);
      setProject(updated);

      // Clear stored draft upon successful save
      clearProjectDraft(getEditProjectDraftKey(id));

      setSuccessMessage("Project details updated successfully.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update project details.");
    } finally {
      setIsSaving(false);
    }
  };

  const handlePublish = async () => {
    if (!id || isOperatingLifecycle) return;
    setError(null);
    setSuccessMessage(null);

    try {
      setIsOperatingLifecycle(true);
      const updated = await publishAdminProject(id);
      setProject(updated);
      setSuccessMessage(`"${updated.title}" is now published on the public website.`);
    } catch (err) {
      if (err instanceof ApiError && err.missingFields) {
        setError(
          `Cannot publish: ${err.message}. Missing required items: ${err.missingFields.join(", ")}.`,
        );
      } else {
        setError(err instanceof Error ? err.message : "Failed to publish project.");
      }
    } finally {
      setIsOperatingLifecycle(false);
    }
  };

  const handleUnpublish = async () => {
    if (!id || isOperatingLifecycle) return;
    setError(null);
    setSuccessMessage(null);

    try {
      setIsOperatingLifecycle(true);
      const updated = await unpublishAdminProject(id);
      setProject(updated);
      setSuccessMessage(`"${updated.title}" was unpublished and returned to draft.`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to unpublish project.");
    } finally {
      setIsOperatingLifecycle(false);
    }
  };

  const handleArchive = async () => {
    if (!id || isOperatingLifecycle) return;
    setError(null);
    setSuccessMessage(null);

    try {
      setIsOperatingLifecycle(true);
      const updated = await archiveAdminProject(id);
      setProject(updated);
      setSuccessMessage(`"${updated.title}" was moved to archive.`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to archive project.");
    } finally {
      setIsOperatingLifecycle(false);
    }
  };

  const handleRestore = async () => {
    if (!id || isOperatingLifecycle) return;
    setError(null);
    setSuccessMessage(null);

    try {
      setIsOperatingLifecycle(true);
      const updated = await restoreAdminProject(id);
      setProject(updated);
      setSuccessMessage(`"${updated.title}" was restored to draft status.`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to restore project.");
    } finally {
      setIsOperatingLifecycle(false);
    }
  };

  const handleDelete = async () => {
    if (!id || !project || isDeleting) return;

    try {
      setIsDeleting(true);
      setError(null);
      await deleteAdminProject(id);
      clearProjectDraft(getEditProjectDraftKey(id));
      router.push("/admin/projects");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to delete project.");
      setShowDeleteModal(false);
    } finally {
      setIsDeleting(false);
    }
  };

  const [isOperatingHomepage, setIsOperatingHomepage] = useState(false);

  const handleToggleHomepageFeature = async () => {
    if (!project || isOperatingHomepage) return;

    if (project.status !== "published") {
      setError("Publish this project before featuring it on the homepage.");
      return;
    }

    try {
      setIsOperatingHomepage(true);
      setError(null);
      setSuccessMessage(null);

      // Fetch all projects to inspect current homepage assignments
      const allProjects = await fetchAdminProjects("all");

      // Build current featured list ONLY from projects satisfying:
      // status === "published" && isFeaturedHomepage === true && homepageOrder != null
      // Exclude current project to prevent accidental duplication
      const currentValidFeatured = allProjects
        .filter(
          (p) =>
            p.id !== project.id &&
            p.status === "published" &&
            p.isFeaturedHomepage === true &&
            p.homepageOrder != null,
        )
        .sort((a, b) => (a.homepageOrder ?? 0) - (b.homepageOrder ?? 0));

      if (project.isFeaturedHomepage) {
        // Remove from homepage: send all other valid featured project IDs
        const nextIds = currentValidFeatured.map((p) => p.id);
        await updateAdminHomepageProjects(nextIds);

        // Immediately refetch project from server to synchronize state
        const refreshed = await fetchAdminProjectById(project.id);
        setProject(refreshed);
        setSuccessMessage(`"${refreshed.title}" removed from homepage featured projects.`);
      } else {
        // Feature on homepage
        if (currentValidFeatured.length >= 3) {
          setError("Maximum 3 projects can be featured on the homepage. Remove one of the current featured projects first.");
          return;
        }

        // Deduplicate before sending
        const nextIds = Array.from(new Set([...currentValidFeatured.map((p) => p.id), project.id]));
        await updateAdminHomepageProjects(nextIds);

        // Immediately refetch project from server to synchronize state
        const refreshed = await fetchAdminProjectById(project.id);
        setProject(refreshed);
        setSuccessMessage(`"${refreshed.title}" is now featured on the homepage (Position #${refreshed.homepageOrder ?? nextIds.length}).`);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update homepage featured status.");
    } finally {
      setIsOperatingHomepage(false);
    }
  };

  if (isLoading) {
    return (
      <div className="loading-container" role="status" aria-live="polite">
        <div className="spinner" />
        <p>Loading project details...</p>
      </div>
    );
  }

  if (!project) {
    return (
      <div className="card">
        <div className="empty-state">
          <h2 className="empty-state-title">Project Not Found</h2>
          <p className="empty-state-desc">The requested project ID does not exist.</p>
          <a href="/admin/projects" className="btn btn-primary">
            Back to Projects
          </a>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", marginBottom: "0.5rem" }}>
            <a href="/admin/projects" className="btn btn-secondary btn-sm">
              &larr; Projects
            </a>
            <StatusBadge
              status={project.status}
              isFeaturedHomepage={project.isFeaturedHomepage}
            />
            {isDirty && (
              <span className="badge badge-draft" title="You have unsaved changes">
                Unsaved changes
              </span>
            )}
          </div>
          <h1>{project.title}</h1>
          <p>
            Slug: <code style={{ color: "var(--accent, #F5C400)" }}>/projects/{project.slug}</code> &bull; Last updated {new Date(project.updatedAt).toLocaleString()}
          </p>
        </div>

        <div className="page-actions">
          <a
            href={`/admin/projects/${project.id}/preview`}
            className="btn btn-secondary"
            title="Preview how this project looks on public site"
          >
            Preview Site Card
          </a>
        </div>
      </div>

      {error && (
        <div className="alert-banner alert-danger" role="alert">
          <span>{error}</span>
        </div>
      )}

      {successMessage && (
        <div className="alert-banner alert-success" role="alert">
          <span>{successMessage}</span>
        </div>
      )}

      <form onSubmit={handleSaveMetadata}>
        {/* Section 1: Core Information */}
        <div className="card">
          <div className="card-header" style={{ marginBottom: "1rem" }}>
            <div>
              <h2 className="card-title">1. Core Information</h2>
              <p className="card-desc">
                Basic project identification, client information, system capacity, and classification.
              </p>
            </div>
            <StatusBadge status={project.status} isFeaturedHomepage={project.isFeaturedHomepage} />
          </div>

          <div className="form-group">
            <label htmlFor="edit-title" className="form-label">
              Project Title <span className="required">*</span>
            </label>
            <input
              id="edit-title"
              type="text"
              className="form-input"
              value={title}
              onChange={(e) => handleTitleChange(e.target.value)}
              required
              maxLength={150}
              disabled={isSaving}
            />
          </div>

          <div className="form-group">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.5rem" }}>
              <label htmlFor="edit-slug" className="form-label" style={{ marginBottom: 0 }}>
                URL Slug
              </label>
              <label style={{ fontSize: "0.8rem", color: "var(--text-secondary)", display: "inline-flex", alignItems: "center", gap: "0.4rem", cursor: "pointer" }}>
                <input
                  type="checkbox"
                  checked={autoSlug}
                  onChange={(e) => {
                    setAutoSlug(e.target.checked);
                    if (e.target.checked && title) {
                      setSlug(slugify(title));
                    }
                  }}
                  disabled={isSaving}
                />
                Auto-generate from title
              </label>
            </div>
            <div className="input-wrapper" style={{ display: "flex", alignItems: "center" }}>
              <span
                style={{
                  backgroundColor: "var(--bg-surface-raised)",
                  color: "var(--text-muted)",
                  padding: "0.65rem 0.85rem",
                  border: "1px solid var(--border-default)",
                  borderRight: "none",
                  borderRadius: "var(--radius-md) 0 0 var(--radius-md)",
                  fontSize: "0.9rem",
                  fontFamily: "monospace",
                }}
              >
                /projects/
              </span>
              <input
                id="edit-slug"
                type="text"
                className="form-input"
                style={{ borderRadius: "0 var(--radius-md) var(--radius-md) 0" }}
                value={slug}
                onChange={(e) => handleSlugChange(e.target.value)}
                maxLength={100}
                disabled={isSaving}
              />
            </div>
            <span className="form-hint">
              Unique slug for public website routing. Changing this alters published URLs.
            </span>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label htmlFor="edit-clientOrganization" className="form-label">
                Client / Organization
              </label>
              <input
                id="edit-clientOrganization"
                type="text"
                className="form-input"
                value={clientOrganization}
                onChange={(e) => setClientOrganization(e.target.value)}
                placeholder="e.g. Attock Flour Mills Ltd."
                maxLength={150}
                disabled={isSaving}
              />
              <span className="form-hint">Client or property name. Required for publishing.</span>
            </div>

            <div className="form-group">
              <label htmlFor="edit-location" className="form-label">
                Location
              </label>
              <input
                id="edit-location"
                type="text"
                className="form-input"
                value={locationField}
                onChange={(e) => setLocationField(e.target.value)}
                placeholder="e.g. Kamra Road, Attock"
                maxLength={150}
                disabled={isSaving}
              />
              <span className="form-hint">City / District / Area. Required for publishing.</span>
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label htmlFor="edit-size" className="form-label">
                Capacity / Project Size
              </label>
              <input
                id="edit-size"
                type="text"
                className="form-input"
                value={size}
                onChange={(e) => setSize(e.target.value)}
                placeholder="e.g. 50 kW On-Grid System"
                maxLength={100}
                disabled={isSaving}
              />
              <span className="form-hint">System size or capacity. Required for publishing.</span>
            </div>

            <div className="form-group">
              <label htmlFor="edit-category" className="form-label">
                Category
              </label>
              <select
                id="edit-category"
                className="form-select"
                value={category}
                onChange={(e) => setCategory(e.target.value as ProjectCategory)}
                disabled={isSaving}
              >
                <option value="">-- Select Category --</option>
                {PROJECT_CATEGORIES.map((cat) => (
                  <option key={cat} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
              <span className="form-hint">Must be one of the approved categories. Required for publishing.</span>
            </div>

            <div className="form-group">
              <label htmlFor="edit-completionDate" className="form-label">
                Completion Date
              </label>
              <input
                id="edit-completionDate"
                type="date"
                className="form-input"
                value={completionDate}
                onChange={(e) => setCompletionDate(e.target.value)}
                disabled={isSaving}
              />
              <span className="form-hint">Exact date completed. Required for publishing new projects.</span>
              {!project.completionDate && project.completionYear && <span className="form-hint">Legacy completion year: {project.completionYear}. Enter the actual date when known.</span>}
            </div>
          </div>
        </div>

        {/* Section 2: Project Narrative & Summary */}
        <div className="card">
          <div className="card-header" style={{ marginBottom: "1rem" }}>
            <div>
              <h2 className="card-title">2. Project Narrative &amp; Summary</h2>
              <p className="card-desc">
                Concise case-study summary and comprehensive technical breakdown.
              </p>
            </div>
          </div>

          <div className="form-group">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.5rem" }}>
              <label htmlFor="edit-shortSummary" className="form-label" style={{ marginBottom: 0 }}>
                Short Summary
              </label>
              <span
                style={{
                  fontSize: "0.8rem",
                  fontWeight: 600,
                  color:
                    shortSummary.length > 400
                      ? "var(--color-danger)"
                      : shortSummary.length > 0 && shortSummary.length < 10
                        ? "var(--color-warning)"
                        : "var(--text-muted)",
                }}
              >
                {shortSummary.length} / 400 characters
              </span>
            </div>
            <textarea
              id="edit-shortSummary"
              className="form-textarea"
              value={shortSummary}
              onChange={(e) => setShortSummary(e.target.value)}
              placeholder="Brief 1-2 sentence overview of the installation, generation capacity, and key achievement (10–400 characters). Required for publishing."
              rows={3}
              maxLength={500}
              disabled={isSaving}
            />
            <span className="form-hint">
              Featured on project cards and summaries. Must be between 10 and 400 characters to publish.
            </span>
          </div>

          <div className="form-group">
            <label htmlFor="edit-fullStory" className="form-label">
              Full Story / Project Details (Optional)
            </label>
            <textarea
              id="edit-fullStory"
              className="form-textarea"
              value={fullStory}
              onChange={(e) => setFullStory(e.target.value)}
              placeholder="Comprehensive installation narrative: site challenges, engineering design, solar panels, inverters, battery storage, and client benefits..."
              rows={6}
              disabled={isSaving}
            />
            <span className="form-hint">
              Detailed technical writeup displayed on the full case study view.
            </span>
          </div>

          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "1rem" }}>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isSaving || !title.trim()}
            >
              {isSaving ? "Saving Changes..." : "Save Changes"}
            </button>
          </div>
        </div>
      </form>

      {/* Section 3: Media & Uploads */}
      <div className="card">
        <div className="card-header" style={{ marginBottom: "1rem" }}>
          <div>
            <h2 className="card-title">3. Media &amp; Uploads</h2>
            <p className="card-desc">
              Manage project photography. Streamed directly into Supabase Storage.
            </p>
          </div>
        </div>

        <ProjectMediaManager
          projectId={project.id}
          media={project.images || []}
          projectStatus={project.status}
          onMediaChange={() => refreshProjectMedia(project.id)}
          disabled={isSaving || isOperatingLifecycle}
        />
      </div>

      {/* Section 4: Status & Actions */}
      <div className="card">
        <div className="card-header" style={{ marginBottom: "1rem" }}>
          <div>
            <h2 className="card-title">4. Status &amp; Actions</h2>
            <p className="card-desc">
              Manage project publication lifecycle, archiving, and deletion.
            </p>
          </div>
          <StatusBadge status={project.status} isFeaturedHomepage={project.isFeaturedHomepage} />
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "1rem 1.25rem",
              backgroundColor: "var(--surface-subtle)",
              borderRadius: "var(--radius-sm)",
              border: "1px solid var(--border)",
              flexWrap: "wrap",
              gap: "1rem",
            }}
          >
            <div>
              <div style={{ fontWeight: 600, fontSize: "0.95rem", color: "var(--text)" }}>
                Publication Status: <span style={{ textTransform: "capitalize" }}>{project.status}</span>
              </div>
              <p style={{ fontSize: "0.82rem", color: "var(--text-muted)", margin: "4px 0 0" }}>
                {project.status === "published"
                  ? "This project is live and visible on the public website."
                  : project.status === "draft"
                    ? "Draft projects are private. At least 1 image and all core fields are required before publishing."
                    : "Archived projects are hidden from the public website and homepage."}
              </p>
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", flexWrap: "wrap" }}>
              {project.status === "draft" && (
                <button
                  type="button"
                  className="btn btn-success"
                  onClick={handlePublish}
                  disabled={isOperatingLifecycle}
                >
                  {isOperatingLifecycle ? <span className="spinner-sm" /> : "Publish to Website"}
                </button>
              )}

              {project.status === "published" && (
                <button
                  type="button"
                  className="btn btn-warning"
                  onClick={handleUnpublish}
                  disabled={isOperatingLifecycle}
                >
                  {isOperatingLifecycle ? <span className="spinner-sm" /> : "Unpublish (to Draft)"}
                </button>
              )}

              {project.status !== "archived" && (
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleArchive}
                  disabled={isOperatingLifecycle}
                >
                  Archive Project
                </button>
              )}

              {project.status === "archived" && (
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleRestore}
                  disabled={isOperatingLifecycle}
                >
                  Restore to Draft
                </button>
              )}
            </div>
          </div>

          {/* Homepage Feature Section */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "1rem 1.25rem",
              backgroundColor: "var(--surface-subtle)",
              borderRadius: "var(--radius-sm)",
              border: "1px solid var(--border)",
              flexWrap: "wrap",
              gap: "1rem",
              marginTop: "1rem",
            }}
          >
            <div>
              <div style={{ fontWeight: 600, fontSize: "0.95rem", color: "var(--text)" }}>
                Homepage Feature:{" "}
                {project.isFeaturedHomepage ? (
                  <span className="badge badge-featured">Featured (#{project.homepageOrder})</span>
                ) : (
                  <span style={{ color: "var(--text-muted)", fontSize: "0.85rem", fontWeight: 400 }}>
                    Not Featured
                  </span>
                )}
              </div>
              <p style={{ fontSize: "0.82rem", color: "var(--text-muted)", margin: "4px 0 0" }}>
                {project.status === "published"
                  ? project.isFeaturedHomepage
                    ? "This project is currently showcased on the public homepage."
                    : "Showcase this published project in the homepage featured section (up to 3 total)."
                  : "Publish this project before featuring it on the homepage."}
              </p>
            </div>

            <div>
              {project.status === "published" ? (
                project.isFeaturedHomepage ? (
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={handleToggleHomepageFeature}
                    disabled={isOperatingHomepage || isOperatingLifecycle}
                  >
                    {isOperatingHomepage ? <span className="spinner-sm" /> : "Remove from Homepage"}
                  </button>
                ) : (
                  <button
                    type="button"
                    className="btn btn-primary"
                    onClick={handleToggleHomepageFeature}
                    disabled={isOperatingHomepage || isOperatingLifecycle}
                  >
                    {isOperatingHomepage ? <span className="spinner-sm" /> : "Feature on Homepage"}
                  </button>
                )
              ) : (
                <button
                  type="button"
                  className="btn btn-secondary"
                  disabled={true}
                  title="Publish this project before featuring it on the homepage."
                >
                  Feature on Homepage
                </button>
              )}
            </div>
          </div>

          {(project.status === "draft" || project.status === "archived") && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "1rem 1.25rem",
                borderRadius: "var(--radius-sm)",
                border: "1px solid rgba(220, 38, 38, 0.25)",
                backgroundColor: "rgba(220, 38, 38, 0.04)",
                flexWrap: "wrap",
                gap: "1rem",
              }}
            >
              <div>
                <div style={{ fontWeight: 600, fontSize: "0.9rem", color: "var(--color-danger)" }}>
                  Danger Zone
                </div>
                <p style={{ fontSize: "0.82rem", color: "var(--text-muted)", margin: "4px 0 0" }}>
                  Permanently delete this project and all associated media from storage.
                </p>
              </div>

              <button
                type="button"
                className="btn btn-outline-danger"
                onClick={() => setShowDeleteModal(true)}
                disabled={isOperatingLifecycle}
              >
                Delete Project
              </button>
            </div>
          )}
        </div>
      </div>

      <ProjectReviewsManager key={id} projectId={id} />
      {showDeleteModal && project && (
        <DeleteConfirmModal
          isOpen={true}
          projectTitle={project.title}
          onConfirm={handleDelete}
          onCancel={() => setShowDeleteModal(false)}
          isDeleting={isDeleting}
        />
      )}
    </div>
  );
}

import { useState, useRef, type ChangeEvent } from "react";
import type { ProjectImageItem, ProjectStatus } from "../../types/admin/project";
import {
  uploadAdminProjectMedia,
  updateAdminProjectMedia,
  deleteAdminProjectMedia,
  reorderAdminProjectMedia,
  setAdminProjectMediaPrimary,
  ApiError,
} from "../../lib/admin/api";

type ProjectMediaManagerProps = {
  projectId: string;
  media: ProjectImageItem[];
  projectStatus: ProjectStatus;
  onMediaChange: () => Promise<void> | void;
  disabled?: boolean;
};

const MAX_IMAGE_BYTES = 5 * 1024 * 1024; // 5 MB
const MAX_IMAGE_COUNT = 5;

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

type PendingUploadItem = {
  id: string;
  file: File;
  name: string;
  size: number;
  status: "waiting" | "uploading" | "done" | "error";
  error?: string;
};

export function ProjectMediaManager({
  projectId,
  media,
  projectStatus,
  onMediaChange,
  disabled = false,
}: ProjectMediaManagerProps) {
  const [isUploading, setIsUploading] = useState(false);
  const [pendingQueue, setPendingQueue] = useState<PendingUploadItem[]>([]);
  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [editingMediaId, setEditingMediaId] = useState<string | null>(null);
  const [editAltText, setEditAltText] = useState("");
  const [editCaption, setEditCaption] = useState("");

  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const sortedImages = [...media].sort((a, b) => a.sortOrder - b.sortOrder);
  const totalOccupied = sortedImages.length + pendingQueue.length;
  const isAtLimit = totalOccupied >= MAX_IMAGE_COUNT;
  const remainingCapacity = MAX_IMAGE_COUNT - sortedImages.length - pendingQueue.length;

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    setError(null);
    setSuccess(null);

    const maxAllowed = MAX_IMAGE_COUNT - sortedImages.length - pendingQueue.length;
    if (maxAllowed <= 0) {
      setError(
        `This project already has ${sortedImages.length} image${sortedImages.length === 1 ? "" : "s"} (maximum ${MAX_IMAGE_COUNT}). Cannot add more.`,
      );
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }

    if (files.length > maxAllowed) {
      setError(
        `This project already has ${sortedImages.length} image${sortedImages.length === 1 ? "" : "s"}. You can add up to ${maxAllowed} more.`,
      );
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }

    const validMimes = ["image/jpeg", "image/png", "image/webp"];
    const newItems: PendingUploadItem[] = [];

    for (const file of files) {
      if (!validMimes.includes(file.type)) {
        setError(`"${file.name}" has an unsupported format. Allowed: JPEG, PNG, or WebP.`);
        if (fileInputRef.current) fileInputRef.current.value = "";
        return;
      }

      if (file.size > MAX_IMAGE_BYTES) {
        setError(`"${file.name}" exceeds 5 MB limit (${formatBytes(file.size)}).`);
        if (fileInputRef.current) fileInputRef.current.value = "";
        return;
      }

      newItems.push({
        id: `${file.name}-${file.size}-${Date.now()}-${Math.random()}`,
        file,
        name: file.name,
        size: file.size,
        status: "waiting",
      });
    }

    setPendingQueue((prev) => [...prev, ...newItems]);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveFromQueue = (id: string) => {
    setPendingQueue((prev) => prev.filter((item) => item.id !== id));
  };

  const handleRetryItem = async (id: string) => {
    if (isUploading) return;
    const item = pendingQueue.find((q) => q.id === id);
    if (!item) return;

    setError(null);
    setSuccess(null);
    setIsUploading(true);

    setPendingQueue((prev) =>
      prev.map((q) => (q.id === id ? { ...q, status: "uploading", error: undefined } : q)),
    );

    const hasPrimary = sortedImages.some((img) => img.isPrimary);
    const isFirst = !hasPrimary && sortedImages.length === 0;
    const defaultAlt = isFirst ? "Project primary image" : "";

    try {
      await uploadAdminProjectMedia(projectId, item.file, {
        altText: defaultAlt || undefined,
        isPrimary: isFirst,
      });

      setPendingQueue((prev) => prev.filter((q) => q.id !== id));
      setSuccess(`"${item.name}" uploaded successfully.`);
      await onMediaChange();
    } catch (err) {
      const isRateLimited =
        (err instanceof ApiError && err.status === 429) ||
        (err instanceof Error && /429|rate limit|too many image upload/i.test(err.message));
      const msg = isRateLimited
        ? "Too many image upload attempts. Please try again later."
        : err instanceof Error
        ? err.message
        : "Upload failed";
      setPendingQueue((prev) =>
        prev.map((q) => (q.id === id ? { ...q, status: "error", error: msg } : q)),
      );
      setError(isRateLimited ? msg : `Upload failed for "${item.name}": ${msg}`);
    } finally {
      setIsUploading(false);
    }
  };

  const handleUploadQueue = async () => {
    const waitingItems = pendingQueue.filter(
      (item) => item.status === "waiting" || item.status === "error",
    );
    if (waitingItems.length === 0 || isUploading) return;

    setError(null);
    setSuccess(null);
    setIsUploading(true);

    let currentImageCount = sortedImages.length;
    let anyError = false;

    for (const item of waitingItems) {
      setPendingQueue((prev) =>
        prev.map((q) =>
          q.id === item.id ? { ...q, status: "uploading", error: undefined } : q,
        ),
      );

      const hasPrimary = sortedImages.some((img) => img.isPrimary);
      const isFirst = !hasPrimary && currentImageCount === 0;
      const defaultAlt = isFirst ? "Project primary image" : "";

      try {
        await uploadAdminProjectMedia(projectId, item.file, {
          altText: defaultAlt || undefined,
          isPrimary: isFirst,
        });

        currentImageCount += 1;
        setPendingQueue((prev) =>
          prev.map((q) => (q.id === item.id ? { ...q, status: "done" } : q)),
        );
      } catch (err) {
        anyError = true;
        const isRateLimited =
          (err instanceof ApiError && err.status === 429) ||
          (err instanceof Error && /429|rate limit|too many image upload/i.test(err.message));
        const msg = isRateLimited
          ? "Too many image upload attempts. Please try again later."
          : err instanceof Error
          ? err.message
          : "Upload failed";

        setPendingQueue((prev) =>
          prev.map((q) => (q.id === item.id ? { ...q, status: "error", error: msg } : q)),
        );
        setError(isRateLimited ? msg : `Upload failed for "${item.name}": ${msg}`);

        // If rate-limited, stop blindly firing further queued requests
        if (isRateLimited) {
          break;
        }
      }
    }

    setIsUploading(false);
    await onMediaChange();

    // Remove successfully uploaded files from queue
    setPendingQueue((prev) => prev.filter((item) => item.status !== "done"));

    if (!anyError) {
      setSuccess("All selected images uploaded successfully.");
    }
  };

  const handleSetPrimary = async (item: ProjectImageItem) => {
    if (item.isPrimary || disabled) return;
    setError(null);
    setSuccess(null);

    try {
      setActionLoadingId(item.id);
      await setAdminProjectMediaPrimary(projectId, item.id);
      setSuccess("Main project image updated.");
      await onMediaChange();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to set primary image.");
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleDelete = async (item: ProjectImageItem) => {
    if (disabled) return;
    if (projectStatus === "published") {
      if (sortedImages.length <= 1) {
        setError("Cannot delete the only image of a published project. Unpublish the project or upload another image first.");
        return;
      }
      if (item.isPrimary) {
        setError("Cannot delete the primary image of a published project. Designate another image as main before deleting this one.");
        return;
      }
    }

    if (!window.confirm("Are you sure you want to delete this image?")) {
      return;
    }

    setError(null);
    setSuccess(null);

    try {
      setActionLoadingId(item.id);
      await deleteAdminProjectMedia(projectId, item.id);
      setSuccess("Image deleted successfully.");
      await onMediaChange();
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setError(err.message);
      } else {
        setError(err instanceof Error ? err.message : "Failed to delete image.");
      }
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleMove = async (index: number, direction: "up" | "down") => {
    const targetIndex = direction === "up" ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= sortedImages.length || disabled) return;

    const reordered = [...sortedImages];
    const temp = reordered[index];
    reordered[index] = reordered[targetIndex];
    reordered[targetIndex] = temp;

    const mediaIds = reordered.map((m) => m.id);

    setError(null);
    setSuccess(null);

    try {
      setActionLoadingId("reorder");
      await reorderAdminProjectMedia(projectId, mediaIds);
      await onMediaChange();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to reorder images.");
    } finally {
      setActionLoadingId(null);
    }
  };

  const startEditing = (item: ProjectImageItem) => {
    setEditingMediaId(item.id);
    setEditAltText(item.altText || "");
    setEditCaption(item.caption || "");
  };

  const cancelEditing = () => {
    setEditingMediaId(null);
    setEditAltText("");
    setEditCaption("");
  };

  const handleSaveMetadata = async (item: ProjectImageItem) => {
    setError(null);
    setSuccess(null);

    try {
      setActionLoadingId(item.id);
      await updateAdminProjectMedia(projectId, item.id, {
        altText: editAltText.trim() || null,
        caption: editCaption.trim() || null,
      });
      setSuccess("Image details updated.");
      setEditingMediaId(null);
      await onMediaChange();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update image details.");
    } finally {
      setActionLoadingId(null);
    }
  };

  return (
    <div className="project-media-manager">
      <div className="media-manager-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <div>
          <h3 style={{ fontSize: "1.1rem", fontWeight: 600, color: "var(--text-primary)" }}>
            Project Images ({sortedImages.length} / {MAX_IMAGE_COUNT})
          </h3>
          <p className="form-hint">
            Upload 1 to 5 images (JPEG, PNG, WebP &le; 5 MB). At least 1 image is required for publishing.
            {remainingCapacity > 0
              ? ` Remaining capacity: ${remainingCapacity} image${remainingCapacity === 1 ? "" : "s"}.`
              : " Maximum capacity reached."}
          </p>
        </div>
        {!isAtLimit && (
          <div>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="image/jpeg,image/png,image/webp"
              multiple
              style={{ display: "none" }}
              id="image-upload-input"
              aria-label="Add Images"
              disabled={disabled || isUploading}
            />
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className={`btn btn-primary ${disabled || isUploading ? "disabled" : ""}`}
              disabled={disabled || isUploading}
              style={{ cursor: disabled || isUploading ? "not-allowed" : "pointer" }}
            >
              {isUploading ? (
                <>
                  <span className="spinner-sm" /> Uploading...
                </>
              ) : (
                <>
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                    <polyline points="17 8 12 3 7 8" />
                    <line x1="12" y1="3" x2="12" y2="15" />
                  </svg>
                  Add Images
                </>
              )}
            </button>
          </div>
        )}
      </div>

      {error && (
        <div className="alert-banner alert-danger" role="alert">
          <span>{error}</span>
        </div>
      )}

      {success && (
        <div className="alert-banner alert-success" role="status">
          <span>{success}</span>
        </div>
      )}

      {/* Pending Upload Queue */}
      {pendingQueue.length > 0 && (
        <div
          className="pending-queue-card"
          style={{
            backgroundColor: "var(--surface)",
            border: "1px solid var(--border)",
            borderRadius: "var(--radius-md)",
            padding: "1.25rem",
            marginBottom: "1.5rem",
            boxShadow: "var(--shadow-subtle)",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "0.85rem",
              flexWrap: "wrap",
              gap: "0.5rem",
            }}
          >
            <div>
              <h4 style={{ fontSize: "0.95rem", fontWeight: 600, color: "var(--text)" }}>
                Selected Images ({pendingQueue.length})
              </h4>
              <p style={{ fontSize: "0.78rem", color: "var(--text-muted)", margin: "2px 0 0" }}>
                Ready to be uploaded to project storage.
              </p>
            </div>
            <button
              type="button"
              className="btn btn-primary btn-sm"
              onClick={handleUploadQueue}
              disabled={isUploading || pendingQueue.every((q) => q.status === "done")}
            >
              {isUploading ? (
                <>
                  <span className="spinner-sm" /> Uploading...
                </>
              ) : (
                `Upload ${pendingQueue.length} Image${pendingQueue.length === 1 ? "" : "s"}`
              )}
            </button>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
            {pendingQueue.map((item) => (
              <div
                key={item.id}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  padding: "0.6rem 0.85rem",
                  backgroundColor: "var(--surface-subtle)",
                  borderRadius: "var(--radius-sm)",
                  border: "1px solid var(--border-subtle)",
                  fontSize: "0.85rem",
                  flexWrap: "wrap",
                  gap: "0.5rem",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", overflow: "hidden" }}>
                  <span
                    style={{
                      fontWeight: 500,
                      color: "var(--text)",
                      textOverflow: "ellipsis",
                      overflow: "hidden",
                      whiteSpace: "nowrap",
                      maxWidth: "240px",
                    }}
                    title={item.name}
                  >
                    {item.name}
                  </span>
                  <span style={{ color: "var(--text-muted)", fontSize: "0.78rem" }}>
                    {formatBytes(item.size)}
                  </span>
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
                  {item.status === "waiting" && (
                    <span className="badge badge-draft">Waiting</span>
                  )}
                  {item.status === "uploading" && (
                    <span className="badge badge-featured">
                      <span className="spinner-sm" style={{ width: "10px", height: "10px" }} /> Uploading
                    </span>
                  )}
                  {item.status === "done" && (
                    <span className="badge badge-published">Uploaded</span>
                  )}
                  {item.status === "error" && (
                    <>
                      <span
                        className="badge"
                        style={{
                          backgroundColor: "#fef2f2",
                          color: "#dc2626",
                          border: "1px solid #fecaca",
                        }}
                        title={item.error}
                      >
                        Failed
                      </span>
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleRetryItem(item.id)}
                        disabled={isUploading}
                        style={{ padding: "0.2rem 0.5rem", fontSize: "0.75rem" }}
                      >
                        Retry
                      </button>
                    </>
                  )}

                  {item.status !== "uploading" && (
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleRemoveFromQueue(item.id)}
                      disabled={isUploading}
                      style={{ padding: "0.2rem 0.5rem", fontSize: "0.75rem" }}
                      aria-label={`Remove ${item.name}`}
                    >
                      Remove
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {sortedImages.length === 0 ? (
        <div className="empty-state" style={{ border: "1px dashed var(--border-default)", borderRadius: "var(--radius-lg)", padding: "2.5rem 1.5rem" }}>
          <svg
            width="48"
            height="48"
            viewBox="0 0 24 24"
            fill="none"
            stroke="var(--text-muted)"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ margin: "0 auto 1rem", display: "block" }}
          >
            <rect width="18" height="18" x="3" y="3" rx="2" ry="2" />
            <circle cx="9" cy="9" r="2" />
            <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21" />
          </svg>
          <h4 className="empty-state-title">No Images Uploaded Yet</h4>
          <p className="empty-state-desc">
            Upload high-resolution project photography. At least one image is required to publish this project.
          </p>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="btn btn-secondary"
            disabled={disabled || isUploading}
            style={{ cursor: disabled || isUploading ? "not-allowed" : "pointer", display: "inline-flex" }}
          >
            Select Images
          </button>
        </div>
      ) : (
        <div className="media-list" style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
          {sortedImages.map((item, index) => {
            const isEditing = editingMediaId === item.id;
            const isLoading = actionLoadingId === item.id || actionLoadingId === "reorder";

            return (
              <div
                key={item.id}
                className="media-card"
                style={{
                  backgroundColor: "var(--surface)",
                  border: item.isPrimary
                    ? "2px solid var(--accent)"
                    : "1px solid var(--border)",
                  borderRadius: "var(--radius-md)",
                  padding: "1rem",
                  display: "grid",
                  gridTemplateColumns: "140px 1fr auto",
                  gap: "1.25rem",
                  alignItems: "center",
                  boxShadow: "var(--shadow-subtle)",
                }}
              >
                {/* Image Preview Box */}
                <div
                  style={{
                    width: "140px",
                    height: "95px",
                    backgroundColor: "var(--background)",
                    borderRadius: "var(--radius-sm)",
                    overflow: "hidden",
                    position: "relative",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    border: "1px solid var(--border)",
                  }}
                >
                  <img
                    src={item.url}
                    alt={item.altText || "Project image"}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                </div>

                {/* Image Information & Inline Edit */}
                <div>
                  <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "0.4rem" }}>
                    {item.isPrimary ? (
                      <span className="badge badge-featured">Main Image</span>
                    ) : (
                      <span className="badge badge-draft">Order #{item.sortOrder + 1}</span>
                    )}
                    <span style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>
                      {item.mimeType}
                    </span>
                  </div>

                  {isEditing ? (
                    <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem", marginTop: "0.5rem" }}>
                      <div>
                        <label style={{ fontSize: "0.75rem", color: "var(--text-secondary)", display: "block", marginBottom: "2px" }}>
                          Alt Text {item.isPrimary && <span className="required" style={{ color: "var(--color-danger)" }}>*</span>}
                        </label>
                        <input
                          type="text"
                          className="form-input"
                          style={{ padding: "0.35rem 0.5rem", fontSize: "0.85rem" }}
                          value={editAltText}
                          onChange={(e) => setEditAltText(e.target.value)}
                          placeholder="Descriptive alt text for accessibility"
                        />
                      </div>
                      <div>
                        <label style={{ fontSize: "0.75rem", color: "var(--text-secondary)", display: "block", marginBottom: "2px" }}>
                          Caption (optional)
                        </label>
                        <input
                          type="text"
                          className="form-input"
                          style={{ padding: "0.35rem 0.5rem", fontSize: "0.85rem" }}
                          value={editCaption}
                          onChange={(e) => setEditCaption(e.target.value)}
                          placeholder="Optional caption displayed with image"
                        />
                      </div>
                      <div style={{ display: "flex", gap: "0.5rem", marginTop: "0.25rem" }}>
                        <button
                          type="button"
                          className="btn btn-primary btn-sm"
                          onClick={() => handleSaveMetadata(item)}
                          disabled={isLoading}
                        >
                          Save
                        </button>
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          onClick={cancelEditing}
                          disabled={isLoading}
                        >
                          Cancel
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div>
                      <p style={{ fontSize: "0.85rem", color: "var(--text-primary)", fontWeight: 500 }}>
                        {item.altText ? `Alt: "${item.altText}"` : <span style={{ color: "var(--text-muted)", fontStyle: "italic" }}>No alt text provided</span>}
                      </p>
                      {item.caption && (
                        <p style={{ fontSize: "0.8rem", color: "var(--text-secondary)", marginTop: "2px" }}>
                          Caption: {item.caption}
                        </p>
                      )}
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        style={{ marginTop: "0.4rem", padding: "0.2rem 0.5rem", fontSize: "0.75rem" }}
                        onClick={() => startEditing(item)}
                        disabled={disabled || isLoading}
                      >
                        Edit Details
                      </button>
                    </div>
                  )}
                </div>

                {/* Image Actions */}
                <div style={{ display: "flex", flexDirection: "column", gap: "0.4rem", alignItems: "flex-end" }}>
                  {!item.isPrimary && (
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleSetPrimary(item)}
                      disabled={disabled || isLoading}
                      title="Designate as the main project card image"
                    >
                      Set as Main
                    </button>
                  )}

                  <div style={{ display: "flex", gap: "0.3rem" }}>
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleMove(index, "up")}
                      disabled={disabled || isLoading || index === 0}
                      aria-label="Move Up"
                      title="Move up"
                    >
                      &uarr;
                    </button>
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleMove(index, "down")}
                      disabled={disabled || isLoading || index === sortedImages.length - 1}
                      aria-label="Move Down"
                      title="Move down"
                    >
                      &darr;
                    </button>
                    <button
                      type="button"
                      className="btn btn-outline-danger btn-sm"
                      onClick={() => handleDelete(item)}
                      disabled={disabled || isLoading}
                      aria-label="Delete Image"
                      title="Delete image"
                    >
                      Delete
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";
import { formatProjectCompletion } from "../../lib/project-date";


import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { fetchAdminProjectById } from "../../lib/admin/api";
import { StatusBadge } from "./StatusBadge";
import type { AdminProject, ProjectImageItem } from "../../types/admin/project";

export function ProjectPreviewPage({ projectId }: { projectId?: string }) {
  const params = useParams();
  const pathnameFallback =
    typeof window !== "undefined"
      ? window.location.pathname.match(/\/admin\/projects\/([^/]+)\/(?:edit|preview)/)?.[1]
      : undefined;
  const paramId =
    typeof params?.id === "string"
      ? params.id
      : Array.isArray(params?.id)
        ? params.id[0]
        : undefined;
  const rawId = (typeof projectId === "string" && projectId.trim()) || paramId || pathnameFallback;
  const id = typeof rawId === "string" ? rawId.trim() : "";
  const [project, setProject] = useState<AdminProject | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);
  const [isExpanded, setIsExpanded] = useState(false);

  useEffect(() => {
    let mounted = true;
    async function load() {
      if (!id) return;
      try {
        setIsLoading(true);
        setError(null);
        const data = await fetchAdminProjectById(id);
        if (mounted) {
          setProject(data);
          const images = data.images || [];
          const primaryIdx = images.findIndex((img) => img.isPrimary);
          setSelectedImageIndex(primaryIdx >= 0 ? primaryIdx : 0);
        }
      } catch (err) {
        if (mounted) {
          setError(err instanceof Error ? err.message : "Failed to load project.");
        }
      } finally {
        if (mounted) {
          setIsLoading(false);
        }
      }
    }

    load();
    return () => {
      mounted = false;
    };
  }, [id]);

  if (isLoading) {
    return (
      <div className="loading-container" role="status" aria-live="polite">
        <div className="spinner" />
        <p>Loading project preview...</p>
      </div>
    );
  }

  if (!project) {
    return (
      <div className="card">
        <div className="empty-state">
          <h2 className="empty-state-title">Project Not Found</h2>
          <p className="empty-state-desc">The project could not be found.</p>
          <a href="/admin/projects" className="btn btn-primary">
            Back to Projects
          </a>
        </div>
      </div>
    );
  }

  const images: ProjectImageItem[] = project.images || [];
  const activeImage = images[selectedImageIndex] || project.mainImage || images[0] || null;
  const activeImageUrl = activeImage?.url || null;
  const activeAlt = activeImage?.altText || project.title;

  return (
    <div>
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", marginBottom: "0.5rem" }}>
            <a href={`/admin/projects/${project.id}/edit`} className="btn btn-secondary btn-sm">
              &larr; Back to Editor
            </a>
            <StatusBadge
              status={project.status}
              isFeaturedHomepage={project.isFeaturedHomepage}
            />
          </div>
          <h1>Public Presentation Preview</h1>
          <p>
            Simulates the interactive case study card as presented to visitors on the Electro Tech website.
          </p>
        </div>

        <div className="page-actions">
          <a href={`/admin/projects/${project.id}/edit`} className="btn btn-primary">
            Edit Details
          </a>
        </div>
      </div>

      {error && (
        <div className="alert-banner alert-danger" role="alert">
          <span>{error}</span>
        </div>
      )}

      {/* Website Preview Container */}
      <div className="preview-container" style={{ maxWidth: "880px", margin: "0 auto" }}>
        <article
          className={`preview-card ${isExpanded ? "expanded" : ""}`}
          style={{
            background: "var(--surface, #FFFFFF)",
            border: "1px solid var(--border, #E6E4DF)",
            borderRadius: "var(--radius-md, 14px)",
            overflow: "hidden",
            boxShadow: "var(--shadow-card, 0 4px 20px rgba(17, 17, 15, 0.05))",
          }}
        >
          {/* Main Media Showcase */}
          <div
            className="preview-image-box"
            style={{
              position: "relative",
              height: "380px",
              backgroundColor: "var(--surface-subtle, #EFECE6)",
              overflow: "hidden",
            }}
          >
            {activeImageUrl ? (
              <img
                src={activeImageUrl}
                alt={activeAlt}
                className="preview-image"
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            ) : (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  height: "100%",
                  color: "var(--text-muted, #6F706B)",
                  fontSize: "0.9rem",
                }}
              >
                No images uploaded
              </div>
            )}
          </div>

          {/* Media Thumbnails Strip */}
          {images.length > 1 && (
            <div
              style={{
                display: "flex",
                gap: "0.5rem",
                padding: "0.75rem 1.5rem",
                backgroundColor: "var(--surface-subtle, #EFECE6)",
                borderBottom: "1px solid var(--border, #E6E4DF)",
                overflowX: "auto",
              }}
            >
              {images.map((img, idx) => (
                <button
                  key={img.id}
                  type="button"
                  onClick={() => setSelectedImageIndex(idx)}
                  style={{
                    width: "72px",
                    height: "48px",
                    borderRadius: "6px",
                    overflow: "hidden",
                    border: idx === selectedImageIndex ? "2px solid var(--accent, #F5C400)" : "1px solid var(--border, #E6E4DF)",
                    padding: 0,
                    cursor: "pointer",
                    backgroundColor: "var(--surface, #FFFFFF)",
                    position: "relative",
                    flexShrink: 0,
                  }}
                  title={img.altText || `Image ${idx + 1}`}
                >
                  <img
                    src={img.url}
                    alt={img.altText || `Thumbnail ${idx + 1}`}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                </button>
              ))}
            </div>
          )}

          {/* Case Study Content */}
          <div className="preview-info" style={{ padding: "1.75rem" }}>
            {/* Category & Status */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.75rem" }}>
              <span
                style={{
                  fontSize: "0.75rem",
                  fontWeight: 600,
                  color: "var(--accent, #F5C400)",
                  textTransform: "uppercase",
                  letterSpacing: "0.05em",
                }}
              >
                {project.category || "Solar Installation"}
              </span>
              {formatProjectCompletion(project) && (
                <span style={{ fontSize: "0.8rem", color: "var(--text-muted, #6F706B)" }}>
                  Completed {formatProjectCompletion(project)}
                </span>
              )}
            </div>

            <h3 className="preview-title" style={{ fontSize: "1.5rem", marginBottom: "1rem", color: "var(--text, #111111)" }}>
              <span>{project.title}</span>
            </h3>

            {/* Metadata Pills */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
                gap: "0.75rem",
                padding: "1rem",
                backgroundColor: "var(--surface-subtle, #EFECE6)",
                borderRadius: "var(--radius-sm, 8px)",
                border: "1px solid var(--border, #E6E4DF)",
                marginBottom: "1.25rem",
              }}
            >
              {project.clientOrganization && (
                <div>
                  <div style={{ fontSize: "0.7rem", color: "var(--text-muted, #6F706B)", textTransform: "uppercase", fontWeight: 600 }}>
                    Client / Organization
                  </div>
                  <div style={{ fontSize: "0.9rem", color: "var(--text, #111111)", fontWeight: 500 }}>
                    {project.clientOrganization}
                  </div>
                </div>
              )}

              {project.location && (
                <div>
                  <div style={{ fontSize: "0.7rem", color: "var(--text-muted, #6F706B)", textTransform: "uppercase", fontWeight: 600 }}>
                    Location
                  </div>
                  <div style={{ fontSize: "0.9rem", color: "var(--text, #111111)", fontWeight: 500 }}>
                    {project.location}
                  </div>
                </div>
              )}

              {project.size && (
                <div>
                  <div style={{ fontSize: "0.7rem", color: "var(--text-muted, #6F706B)", textTransform: "uppercase", fontWeight: 600 }}>
                    Capacity / Size
                  </div>
                  <div style={{ fontSize: "0.9rem", color: "var(--text, #111111)", fontWeight: 600 }}>
                    {project.size}
                  </div>
                </div>
              )}
            </div>

            {/* Short Summary */}
            {project.shortSummary ? (
              <div style={{ marginBottom: "1.25rem" }}>
                <p style={{ fontSize: "1rem", color: "var(--text, #111111)", lineHeight: 1.6, fontWeight: 400 }}>
                  {project.shortSummary}
                </p>
              </div>
            ) : project.description ? (
              <div style={{ marginBottom: "1.25rem" }}>
                <p style={{ fontSize: "0.95rem", color: "var(--text-muted, #6F706B)", lineHeight: 1.6 }}>
                  {project.description}
                </p>
              </div>
            ) : null}

            {/* Full Story Section */}
            {project.fullStory && (
              <div style={{ borderTop: "1px solid var(--border, #E6E4DF)", paddingTop: "1.25rem", marginTop: "1.25rem" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.75rem" }}>
                  <h4 style={{ fontSize: "0.95rem", fontWeight: 600, color: "var(--text, #111111)", textTransform: "uppercase", letterSpacing: "0.04em", margin: 0 }}>
                    Project Story &amp; Technical Breakdown
                  </h4>
                  <button
                    type="button"
                    className="btn btn-secondary btn-sm"
                    onClick={() => setIsExpanded((prev) => !prev)}
                    style={{ fontSize: "0.75rem", padding: "0.25rem 0.5rem" }}
                  >
                    {isExpanded ? "Collapse" : "Read Full Story"}
                  </button>
                </div>

                {isExpanded && (
                  <div style={{ fontSize: "0.9rem", color: "var(--text-muted, #6F706B)", lineHeight: 1.7, whiteSpace: "pre-wrap" }}>
                    {project.fullStory}
                  </div>
                )}
              </div>
            )}
          </div>
        </article>
      </div>
    </div>
  );
}

